import csv

def load(path):
    with open(path,newline='') as f:
        r=csv.DictReader(f)
        rows=list(r)
    return r.fieldnames, rows

for path,name in [('/root/bus_pass_schedule_input.csv','bus'),('/root/rail_pass_schedule_input.csv','rail')]:
    headers,rows=load(path)
    print(name,'rows',len(rows),'cols',len(headers))
    print('headers',headers)
    sums={}
    for col in headers:
        if col=='vendor' or col=='comments':
            continue
        try:
            float(rows[0][col])
        except:
            continue
        s=0.0
        for row in rows:
            v=row[col]
            if v=='' or v is None:
                continue
            s+=float(v)
        sums[col]=s
    for col in ['beginning_balance','jan_adds','jan_amortization','jan_ending_balance','feb_adds','feb_amortization','feb_ending_balance','mar_adds','mar_amortization','mar_ending_balance','apr_adds','apr_amortization','apr_ending_balance']:
        if col in sums:
            print(col, round(sums[col],2))
    print('account_numbers',sorted(set(r['account_number'] for r in rows if r.get('account_number'))))
    print()
